create extension if not exists btree_gist with schema extensions;
create schema if not exists agenda_private;
revoke all on schema agenda_private from public;
grant usage on schema agenda_private to anon,authenticated;
create table agenda_private.admins(email text primary key);
alter table agenda_private.admins enable row level security;
revoke all on agenda_private.admins from public,anon,authenticated;
insert into agenda_private.admins values ('cabanadasmansoes@gmail.com'),('rayvooficial@gmail.com');
create function agenda_private.is_admin() returns boolean language sql stable security definer set search_path='' as $$
select auth.uid() is not null and exists(select 1 from auth.users u join agenda_private.admins a on lower(u.email)=a.email where u.id=auth.uid() and u.email_confirmed_at is not null) $$;
revoke all on function agenda_private.is_admin() from public;
grant execute on function agenda_private.is_admin() to authenticated;
create function public.agenda_is_admin() returns boolean language sql stable security invoker set search_path='' as $$ select agenda_private.is_admin() $$;
revoke all on function public.agenda_is_admin() from public;
grant execute on function public.agenda_is_admin() to authenticated;
create table public.agenda_bookings(id uuid primary key default gen_random_uuid(),cabin text not null check(cabin in ('eden','manancial','casa')),start date not null,"end" date not null,guest text not null check(length(trim(guest)) between 1 and 120),phone text not null default '' check(length(phone)<=40),notes text not null default '' check(length(notes)<=2000),status text not null check(status in ('confirmed','pending','blocked')),check("end">start),exclude using gist(cabin with =,daterange(start,"end",'[)') with &&));
alter table public.agenda_bookings enable row level security;
revoke all on public.agenda_bookings from public,anon,authenticated;
grant select,insert,update,delete on public.agenda_bookings to authenticated;
create policy agenda_admins on public.agenda_bookings for all to authenticated using((select agenda_private.is_admin())) with check((select agenda_private.is_admin()));
create function agenda_private.availability() returns table(cabin text,start date,"end" date) language sql stable security definer set search_path='' as $$select b.cabin,b.start,b."end" from public.agenda_bookings b order by b.start$$;
revoke all on function agenda_private.availability() from public;
grant execute on function agenda_private.availability() to anon,authenticated;
create function public.agenda_availability() returns table(cabin text,start date,"end" date) language sql stable security invoker set search_path='' as $$select * from agenda_private.availability()$$;
revoke all on function public.agenda_availability() from public;
grant execute on function public.agenda_availability() to anon,authenticated;